"instrument_create_receipts","instrument_staged_uploads","site_editor_receipts"],"buckets":["instrument-media","instrument-documents","service-evidence"],"storagePolicy":{"using_expression":"(bucket_id <> ALL (ARRAY['instrument-media'::text, 'instrument-documents'::text, 'service-evidence'::text]))","check_expression":"(bucket_id <> ALL (ARRAY['instrument-media'::text, 'instrument-documents'::text, 'service-evidence'::text]))"},"constraints":[["instrument_create_receipts","p",["owner_id","idempotency_key"]],["instrument_create_receipts","u",["owner_id","upload_id"]],["instrument_staged_uploads","p",["bucket_id","storage_path"]],["site_editor_receipts","p",["actor_user_id","request_id"]]],"columns":[{"table":"profiles","name":"id","type":"uuid","not_null":true},{"table":"profiles","name":"role","type":"member_role","not_null":true},{"table":"profiles","name":"plan","type":"plan_tier","not_null":true},{"table":"profiles","name":"account_status","type":"text","not_null":true},{"table":"guitars","name":"id","type":"uuid","not_null":true},{"table":"guitars","name":"owner_id","type":"uuid","not_null":false},{"table":"guitars","name":"qr_code","type":"text","not_null":true},{"table":"guitars","name":"permanent_path","type":"text","not_null":true},{"table":"guitars","name":"serial_number","type":"text","not_null":false},{"table":"guitars","name":"no_serial_used","type":"boolean","not_null":true},{"table":"guitars","name":"status","type":"guitar_status","not_null":true},{"table":"guitars","name":"owner_removed_at","type":"timestamp with time zone","not_null":false},{"table":"guitars","name":"owner_removed_by","type":"uuid","not_null":false},{"table":"guitars","name":"owner_removed_reason","type":"text","not_null":false},{"table":"guitars","name":"admin_archived_at","type":"timestamp with time zone","not_null":false},{"table":"guitars","name":"updated_at","type":"timestamp with time zone","not_null":true},{"table":"ownership_transfers","name":"guitar_id","type":"uuid","not_nu