nt_staged_uploads","name":"owner_id","type":"uuid","not_null":true},{"table":"instrument_staged_uploads","name":"upload_id","type":"text","not_null":true},{"table":"instrument_staged_uploads","name":"state","type":"text","not_null":true},{"table":"instrument_staged_uploads","name":"guitar_id","type":"uuid","not_null":false},{"table":"site_editor_receipts","name":"actor_user_id","type":"uuid","not_null":true},{"table":"site_editor_receipts","name":"request_id","type":"uuid","not_null":true},{"table":"site_editor_receipts","name":"request_body","type":"jsonb","not_null":true},{"table":"site_editor_receipts","name":"result","type":"jsonb","not_null":true}],"provenanceTriggers":[["guitar_timeline_events","protect_service_provider_provenance_trigger","CREATE TRIGGER protect_service_provider_provenance_trigger BEFORE INSERT OR DELETE OR UPDATE ON public.guitar_timeline_events FOR EACH ROW EXECUTE FUNCTION protect_service_provider_provenance()"],["guitar_timeline_events","protect_system_timeline_event_trigger","CREATE TRIGGER protect_system_timeline_event_trigger BEFORE DELETE OR UPDATE ON public.guitar_timeline_events FOR EACH ROW EXECUTE FUNCTION protect_system_timeline_event()"],["guitars","create_profile_timeline_event_trigger","CREATE TRIGGER create_profile_timeline_event_trigger AFTER INSERT ON public.guitars FOR EACH ROW EXECUTE FUNCTION create_profile_timeline_event()"],["guitars","set_guitar_no_serial_flag_trigger","CREATE TRIGGER set_guitar_no_serial_flag_trigger BEFORE INSERT OR UPDATE OF serial_number ON public.guitars FOR EACH ROW EXECUTE FUNCTION set_guitar_no_serial_flag()"],["guitars","sync_guitar_serial_alias_trigger","CREATE TRIGGER sync_guitar_serial_alias_trigger AFTER INSERT OR UPDATE OF serial_number ON public.guitars FOR EACH ROW EXECUTE FUNCTION sync_guitar_serial_alias()"]]}$manifest$::jsonb;
 flags jsonb := jsonb_build_object('catalog_readable',false,'required_functions',false,'function_security',false,'blocked_function_grants',false,'private_tables',false,'private_table_grants',false,'server_only_policies',false,'private_storage_buckets',false,'private_storage_policy',false,'receipt_constraints',false,'editor_versioning',false,'schema_columns',false,'public_schema_create',false,'self_security',false);
 item jsonb; signature text; table_name text; role_name text; privilege_name text; proc_oid oid; table_oid oid;
 role_ids oid[]; p record; col record; bucket_count integer; check_name text; entries jsonb;
begin
 begin
  select array_agg(oid order by oid) into role_ids from pg_roles where rolname in ('anon','authenticated');
  if coalesce(array_length(role_ids,1),0)<>2 or not exists(select 1 from pg_roles where rolname='service_role') then
    raise exception 'Required execution roles unavailable';
  end if;
  flags:=jsonb_build_object('catalog_readable',true,'required_functions',true,'function_security',true,'blocked_function_grants',true,'private_tables',true,'private_table_grants',true,'server_only_policies',true,'private_storage_buckets',true,'private_storage_policy',true,'receipt_constraints',true,'editor_versioning',true,'schema_columns',true,'public_schema_create',true,'self_security',true);
  for item in select value from jsonb_array_elements(manifest->'fingerprints') loop
    proc_oid:=null;
    begin proc_oid:=to_regprocedure(item->>'signature'); exception when others then proc_oid:=null; end;
    if proc_oid is null then
      flags:=flags||'{"required_functions":false,"function_security":false}'::jsonb;
    else
      select * into p from pg_proc where oid=proc_oid;
      if encode(sha256(convert_to(replace(p.prosrc,E'\r\n',E'\n'),'UTF8')),'hex') is distinct from item->>'source_hash'
        or pg_get_function_arguments(proc_oid) is distinct from item->>'arguments'
        or pg_get_function_result(proc_oid) is distinct from item->>'result'
        or to_jsonb(p.prosecdef) is distinct from item->'definer'
        or to_jsonb(p.provolatile::text) is distinct from item->'volatility'
        or coalesce(to_jsonb(p.proconfig),'null'::jsonb) is distinct from item->'settings' then
        flags:=jsonb_set(flags,'{function_security}','false');
      end if;
    end if;
  end loop;
  for signature in select jsonb_array_elements_text(manifest->'serviceFunctions') loop
    proc_oid:=to_regprocedure(signature);
    if proc_oid is null then flags:=flags||'{"required_functions":false,"function_security":false}'::jsonb;
    elsif not has_function_privilege('service_role',proc_oid,'EXECUTE')
      or has_function_privilege('anon',proc_oid,'EXECUTE') or has_function_privilege('authenticated',proc_oid,'EXECUTE')
      or exists(select 1 from pg_proc f cross join lateral aclexplode(coalesce(f.proacl,acldefault('f',f.proowner))) a where f.oid=proc_oid and a.grantee=0 and a.privilege_type='EXECUTE') then
      flags:=jsonb_set(flags,'{function_security}','false');
    end if;
  end loop;
  for signature in select jsonb_array_elements_text(manifest->'blockedFunctions') loop
    proc_oid:=to_regprocedure(signature);
    if proc_oid is null or has_function_privilege('service_role',proc_oid,'EXECUTE')
      or has_function_privilege('anon',proc_oid,'EXECUTE') or has_function_privilege('authenticated',proc_oid,'EXECUTE') then
      flags:=jsonb_set(flags,'{blocked_function_grants}','false');
    end if;
  end loop;
  for table_name in select jsonb_array_elements_text(manifest->'tables') loop
    table_oid:=to_regclass('public.'||table_name);
    if table_oid is null or not exists(select 1 from pg_class where oid=table_oid and relkind='r' and relrowsecurity) then
      flags:=jsonb_set(flags,'{private_tables}','false');
    end if;
    if table_oid is null then flags:=jsonb_set(flags,'{private_table_grants}','false');
    else
      foreach role_name in array array['anon','authenticated'] loop
        if has_table_privilege(role_name,table_oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
          or has_any_column_privilege(role_name,table_oid,'SELECT,INSERT,UPDATE,REFERENCES') then
          flags:=jsonb_set(flags,'{private_table_grants}','false');
        end if;
      end loop;
      foreach privilege_name in array array['SELECT','INSERT','UPDATE','DELETE'] loop
        if not has_table_privilege('service_role',table_oid,privilege_name) then flags:=jsonb_set(flags,'{private_table_grants}','false'); end if;
      end loop;
    end if;
  end loop;
  for table_name in select jsonb_array_elements_text(manifest->'baseTables') loop
    if not exists(select 1 from pg_policy where polrelid=to_regclass('public.'||table_name)
      and polname='qrguitar_server_api_only' and not polpermissive and polcmd='*'
      and polroles @> role_ids and polroles <@ role_ids
      and pg_get_expr(polqual,polrelid)='false' and pg_get_expr(polwithcheck,polrelid)='false') then
      flags:=jsonb_set(flags,'{server_only_policies}','false');
    end if;
  end loop;
  select count(*) into bucket_count from storage.buckets
    where id in ('instrument-media','instrument-documents','service-evidence') and public is false;
  flags:=jsonb_set(flags,'{private_storage_buckets}',to_jsonb(bucket_count=3));
  if not exists(select 1 from pg_policy where polrelid=to_regclass('storage.objects')
    and polname='qrguitar_server_owned_files' and not polpermissive and polcmd='*'
    and polroles @> role_ids and polroles <@ role_ids
    and pg_get_expr(polqual,polrelid)=manifest->'storagePolicy'->>'using_expression'
    and pg_get_expr(polwithcheck,polrelid)=manifest->'storagePolicy'->>'check_expression')
    or not exists(select 1 from pg_class where oid=to_regclass('storage.objects') and relrowsecurity) then
    flags:=jsonb_set(flags,'{private_storage_policy}','false');
  end if;
  for item in select value from jsonb_array_elements(manifest->'constraints') loop
    if not exists(select 1 from pg_constraint c where c.conrelid=to_regclass('public.'||(item->>0))
      and c.contype::text=item->>1 and c.convalidated and not c.condeferrable
      and (select jsonb_agg(a.attname order by k.ordinality) from unnest(c.conkey) with ordinality k(attnum,ordinality)
        join pg_attribute a on a.attrelid=c.conrelid and a.attnum=k.attnum)=item->2) then
      flags:=jsonb_set(flags,'{receipt_constraints}','false');
    end if;
  end loop;
  for item in select value from jsonb_array_elements(manifest->'columns') loop
    if not exists(select 1 from pg_attribute where attrelid=to_regclass('public.'||(item->>'table'))
      and attname=item->>'name' and attnum>0 and not attisdropped and format_type(atttypid,atttypmod)=item->>'type'
      and to_jsonb(attnotnull)=item->'not_null') then flags:=jsonb_set(flags,'{schema_columns}','false'); end if;
  end loop;
  for item in select value from jsonb_array_elements(manifest->'provenanceTriggers') loop
    if not exists(select 1 from pg_trigger where tgrelid=to_regclass('public.'||(item->>0)) and tgname=item->>1
      and not tgisinternal and tgenabled in ('O','A') and pg_get_triggerdef(oid)=item->>2) then flags:=jsonb_set(flags,'{schema_columns}','false'); end if;
  end loop;
  if not exists(select 1 from pg_attribute where attrelid=to_regclass('public.site_content') and attname='editor_version' and atttypid='uuid'::regtype and not attisdropped)
    or not exists(select 1 from pg_trigger where tgrelid=to_regclass('public.site_content') and tgname='site_content_editor_version'
      and not tgisinternal and tgenabled in ('O','A') and tgtype=23 and tgfoid=to_regprocedure('public.assign_site_editor_version()')) then
    flags:=jsonb_set(flags,'{editor_versioning}','false');
  end if;
  if has_schema_privilege('anon','public','CREATE') or has_schema_privilege('authenticated','public','CREATE') then
    flags:=jsonb_set(flags,'{public_schema_create}','false');
  end if;
  proc_oid:=to_regprocedure('public.qrguitar_release_readiness()');
  if proc_oid is null or not has_function_privilege('service_role',proc_oid,'EXECUTE')
    or has_function_privilege('anon',proc_oid,'EXECUTE') or has_function_privilege('authenticated',proc_oid,'EXECUTE')
    or not exists(select 1 from pg_proc where oid=proc_oid and prosecdef and provolatile='s' and prorettype='jsonb'::regtype
      and proconfig=array['search_path=pg_catalog, public']::text[]) then
    flags:=jsonb_set(flags,'{self_security}','false');
  end if;
 exception when others then flags:=jsonb_set(flags,'{catalog_readable}','false');
 end;
 select jsonb_agg(jsonb_build_object('name',v.name,'ok',coalesce((flags->>v.name)::boolean,false)) order by v.position)
 into entries from jsonb_array_elements_text(manifest->'checks') with ordinality v(name,position);
 return jsonb_build_object('ready',not exists(select 1 from jsonb_each(flags) where value is distinct from 'true'::jsonb),
   'releaseVersion','2026-09-10.1','checks',entries);
end $readiness$;
revoke all on function public.qrguitar_release_readiness() from public,anon,authenticated;
grant execute on function public.qrguitar_release_readiness() to service_role;
notify pgrst,'reload schema';
